(7700718, 1264092, 67258, '<td valign="top">Very cool find.  Its a shame that large areas of the snow have blown - normally that would be a huge negative for me, but in this instance, the impact of the scene itself prevents a low score.</td>', 'Very cool find.  Its a shame that large areas of the snow have blown - normally that would be a huge negative for me, but in this instance, the impact of the scene itself prevents a low score.', '2021-09-08 13:29:03.000000', NULL, 1),
(7700719, 1263873, 67258, '<td valign="top">Super curves!  Its a totally alie n landscape to me,so an interesting photo.</td>', 'Super curves!  Its a totally alie n landscape to me,so an interesting photo.', '2021-09-08 13:30:03.000000', NULL, 1),
(7700720, 1264023, 96751, '<td valign="top">Hey, I know this path!</td>', 'Hey, I know this path!', '2021-09-08 13:33:06.000000', NULL, 1),
(7700721, 1263934, 67258, '<td valign="top">I like the surprise of this.  The ultra hard, straight, converging  lines contrasting with the soft, natural, pastoral scene.  And  an empty road!</td>', 'I like the surprise of this.  The ultra hard, straight, converging  lines contrasting with the soft, natural, pastoral scene.  And  an empty road!', '2021-09-08 13:36:23.000000', NULL, 1),
