(7700723, 1264097, 67258, '<td valign="top">Not so keen on the green toning, but a lovely scene nonetheless.  Id love to explore the area.</td>', 'Not so keen on the green toning, but a lovely scene nonetheless.  Id love to explore the area.', '2021-09-08 13:37:32.000000', NULL, 1),
(7700725, 1263909, 67258, '<td valign="top">A very different take on the challenge, and took me a while to understand it - we dont have any raised motorways in my part of the UK.  A really well considered abstract composition.</td>', 'A very different take on the challenge, and took me a while to understand it - we dont have any raised motorways in my part of the UK.  A really well considered abstract composition.', '2021-09-08 13:39:07.000000', NULL, 1),
(7700726, 1264113, 67258, '<td valign="top">Brilliant.  I went sheep hunting for my entry, but they didnt want to model for me today.  This is such an interesting photograph.</td>', 'Brilliant.  I went sheep hunting for my entry, but they didnt want to model for me today.  This is such an interesting photograph.', '2021-09-08 13:40:22.000000', NULL, 1),
(7700727, 1264100, 67258, '<td valign="top">I like the contrast of the rural desert-like environment with the dark contrast of the man made road.  As an aside, what an impressively smooth road it is!</td>', 'I like the contrast of the rural desert-like environment with the dark contrast of the man made road.  As an aside, what an impressively smooth road it is!', '2021-09-08 13:42:13.000000', NULL, 1),
